// SHHH! - Don't Wake Mom! - official trailer (picture track).
// Timeline: ./trailer_timeline.json, generated by VideoProduction/07_Trailer/build_trailer_timeline.py (single source of truth).
// Audio is mixed separately (VideoProduction/07_Trailer/mix_trailer_audio.py) and muxed by FFmpeg, so this composition is silent.
import React from 'react';
import {
  AbsoluteFill, Img, OffthreadVideo, Sequence, continueRender, delayRender, interpolate, spring, staticFile,
  useCurrentFrame, useVideoConfig, Easing,
} from 'remotion';
import timeline from './trailer_timeline.json';

export const BRAND = {
  navy: '#19183F', night: '#10132F', yellow: '#FFD65A', coral: '#FF7769', teal: '#65C8C5', purple: '#7958BB', cream: '#FFF3DD', ink: '#2A214B',
};

type Item = {
  id: string; kind: 'shot' | 'card' | 'logo' | 'black'; from: number; frames: number; note: string;
  proxy?: string; zoom?: number[]; text?: string; logo?: string; tagline?: string;
};

const fontHandle = { done: false };
const useBrandFonts = () => {
  const [handle] = React.useState(() => (fontHandle.done ? null : delayRender('brand fonts')));
  React.useEffect(() => {
    if (!handle) return;
    const faces = [
      new FontFace('LuckiestGuy', `url(${staticFile('fonts/LuckiestGuy-Regular.ttf')})`),
      new FontFace('Fredoka', `url(${staticFile('fonts/Fredoka-SemiBold.ttf')})`),
    ];
    Promise.all(faces.map((f) => f.load())).then((loaded) => {
      loaded.forEach((f) => document.fonts.add(f)); fontHandle.done = true; continueRender(handle);
    }).catch((e) => { console.error(e); continueRender(handle); });
  }, [handle]);
};

// A few soft stars (deterministic, slow twinkle - no flashing).
const STARS = Array.from({length: 46}, (_, i) => {
  const r = (n: number) => { const x = Math.sin(i * 127.1 + n * 311.7) * 43758.5453; return x - Math.floor(x); };
  return {x: r(1) * 100, y: r(2) * 70, s: 2 + r(3) * 4, p: r(4) * Math.PI * 2};
});
const NightSky: React.FC<{frame: number}> = ({frame}) => (
  <AbsoluteFill style={{background: `radial-gradient(ellipse at 50% 40%, #2A2470 0%, ${BRAND.navy} 55%, ${BRAND.night} 100%)`}}>
    {STARS.map((st, i) => (
      <div key={i} style={{
        position: 'absolute', left: `${st.x}%`, top: `${st.y}%`, width: st.s, height: st.s, borderRadius: '50%', background: BRAND.cream,
        opacity: 0.35 + 0.35 * (0.5 + 0.5 * Math.sin(frame / 22 + st.p)),
      }} />
    ))}
  </AbsoluteFill>
);

const Vignette: React.FC = () => (
  <AbsoluteFill style={{pointerEvents: 'none', background: 'radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 58%, rgba(8,6,24,0.42) 100%)'}} />
);

const Shot: React.FC<{it: Item; fadeIn: boolean}> = ({it, fadeIn}) => {
  const f = useCurrentFrame();
  const [z0, z1] = it.zoom ?? [1, 1];
  const z = interpolate(f, [0, it.frames], [z0, z1], {extrapolateRight: 'clamp', easing: Easing.inOut(Easing.quad)});
  const op = fadeIn ? interpolate(f, [0, 6], [0, 1], {extrapolateRight: 'clamp'}) : 1;
  return (
    <AbsoluteFill style={{backgroundColor: 'black', opacity: op}}>
      <AbsoluteFill style={{transform: `scale(${z})`, transformOrigin: '50% 0%'}}>
        <OffthreadVideo src={staticFile(it.proxy!)} muted style={{width: '100%', height: '100%', objectFit: 'cover'}} />
      </AbsoluteFill>
      <Vignette />
    </AbsoluteFill>
  );
};

const Card: React.FC<{it: Item}> = ({it}) => {
  const f = useCurrentFrame(); const {fps} = useVideoConfig();
  const pop = spring({frame: f, fps, config: {damping: 11, stiffness: 140, mass: 0.7}});
  const out = interpolate(f, [it.frames - 5, it.frames], [1, 0], {extrapolateLeft: 'clamp'});
  return (
    <AbsoluteFill>
      <NightSky frame={f} />
      <AbsoluteFill style={{justifyContent: 'center', alignItems: 'center', opacity: out}}>
        <div style={{
          fontFamily: 'LuckiestGuy', fontSize: 168, letterSpacing: 4, color: BRAND.yellow, transform: `scale(${0.82 + 0.18 * pop}) rotate(${(1 - pop) * -3}deg)`,
          opacity: Math.min(1, pop * 1.6), WebkitTextStroke: `14px ${BRAND.ink}`, paintOrder: 'stroke fill',
          textShadow: `0 12px 0 ${BRAND.ink}, 0 18px 30px rgba(0,0,0,0.45)`,
        }}>{it.text}</div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

const Logo: React.FC<{it: Item}> = ({it}) => {
  const f = useCurrentFrame(); const {fps} = useVideoConfig();
  const pop = spring({frame: f - 4, fps, config: {damping: 10, stiffness: 90, mass: 0.9}});
  const float = Math.sin(f / 26) * 6;
  const tag = interpolate(f, [fps * 3.6, fps * 4.4], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
  const fadeIn = interpolate(f, [0, 10], [0, 1], {extrapolateRight: 'clamp'});
  const fadeOut = interpolate(f, [it.frames - 24, it.frames], [1, 0], {extrapolateLeft: 'clamp'});
  return (
    <AbsoluteFill style={{backgroundColor: 'black'}}>
      <AbsoluteFill style={{opacity: fadeIn * fadeOut}}>
        <NightSky frame={f} />
        <AbsoluteFill style={{justifyContent: 'center', alignItems: 'center'}}>
          <Img src={staticFile(it.logo!)} style={{
            width: 760, height: 760, marginTop: -90, transform: `translateY(${float}px) scale(${0.55 + 0.45 * pop})`, opacity: Math.min(1, pop * 2),
            filter: 'drop-shadow(0 22px 34px rgba(0,0,0,0.5))',
          }} />
        </AbsoluteFill>
        <AbsoluteFill style={{justifyContent: 'flex-end', alignItems: 'center', paddingBottom: 92}}>
          <div style={{fontFamily: 'Fredoka', fontSize: 56, color: BRAND.cream, opacity: tag, transform: `translateY(${(1 - tag) * 16}px)`,
            textShadow: '0 4px 14px rgba(0,0,0,0.5)', letterSpacing: 1}}>{it.tagline}</div>
        </AbsoluteFill>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export const ShhhTrailer: React.FC = () => {
  useBrandFonts();
  const items = timeline.items as Item[];
  return (
    <AbsoluteFill style={{backgroundColor: 'black'}}>
      {items.map((it, i) => {
        const prev = items[i - 1];
        const fadeIn = !prev || prev.kind !== 'shot' || it.id.startsWith('A') || it.id.startsWith('E5') || it.id.startsWith('E6');
        return (
          <Sequence key={it.id} from={it.from} durationInFrames={it.frames} name={`${it.id} ${it.note}`}>
            {it.kind === 'shot' && <Shot it={it} fadeIn={fadeIn} />}
            {it.kind === 'card' && <Card it={it} />}
            {it.kind === 'logo' && <Logo it={it} />}
            {it.kind === 'black' && <AbsoluteFill style={{backgroundColor: 'black'}} />}
          </Sequence>
        );
      })}
    </AbsoluteFill>
  );
};

export const TRAILER_FRAMES = timeline.durationInFrames as number;
